// DM mission files: local cases S11–S20. Checks: [stat or 'a|b', band, when, pass, fail].
const PED = n => `systems/the-smoke/assets/tokens/people/ped-${String(n).padStart(2, '0')}.webp`;
export default {
  s11: {
    brief: `A buyer keeps selling a small painting, and every time, it ends up back in their bag. Ghost? Scam? Lucky charm? They want answers before a posh private dinner on Friday. What's really going on: the seller's grown-up child keeps stealing it back, because it was a sentimental family gift. A visiting dealer has been hyping its value to sell a made-up history. The twist: the painting shows Auntie Pat's arches in the 1970s. The child's grandad painted it.`,
    openTitle: `Read aloud: it keeps coming back`,
    open: `The buyer lays a small oil painting on the table between you: a railway arch in brown and gold, a bicycle leaning against it, a woman in a headscarf. "Every time I sell this little painting," she says, "it ends up back in my bag." She looks genuinely spooked. "Three times. Three buyers. Three times it's been back in my bag the next morning." She lowers her voice. "Spooky? Profitable? A con? I'll pay for an answer before Friday's private dinner."`,
    cast: ['luca-ferretti', 'viv-shore', 'grace-okafor'],
    people: {'sam-okafor': {name: 'Sam Okafor', role: 'Grown-up grandchild who keeps taking the painting back', img: PED(13), look: 'Twenty-five, paint on his trainers, a backpack, fast hands.', manner: 'Shy, stubborn, embarrassed to be caught.', wants: 'His grandad\'s painting to stay in the family.', line: 'Grandad painted it. She had no right to sell it.'}, 'auntie-pat': {}},
    roles: {'luca-ferretti': `Restorer at the De Beauvoir Deli's back table. Can date the paint.`, 'viv-shore': `The visiting dealer hyping a made-up history. Slightly broke.`, 'grace-okafor': `Sam's grandmother. The painting was a gift from her late husband.`, 'sam-okafor': `Keeps stealing it back.`, 'auntie-pat': `Off stage. The woman in the headscarf in the painting.`},
    scenes: [
      {at: 'DB2.3', title: `The De Beauvoir Deli, the back table`, read: `The back table at the De Beauvoir Deli. Luca Ferretti, in his paint-flecked apron with a loupe on a cord, holds the painting under a lamp. "Seventies," he says. "Oil on board. Local hand." He turns it over. On the back, in pencil: "For Grace, love J. — Morning Lane, 1976." He looks up. "This was a gift. Someone loved someone."`,
        text: `The photographs side by side: the painting in three different sale listings, each with a different made-up history from Viv Shore.`,
        checks: [['sav', 'medium', `Compare Viv's three sale listings and spot the lies`, `"Belgian estate." "Gallery provenance." "Private collection." All invented. The pencil on the back tells the truth.`, `They all sound plausible.`],
          ['grt', 'easy', `Sit with Luca while he cleans a corner to check the signature`, `"J. Okafor." Grace's husband.`, `You leave before he's done.`]]},
      {at: 'DB5.2', title: `The private exchange at The Scolt Head`, read: `The saloon at The Scolt Head. Viv Shore, in a leopard-print coat with two phones, is showing the painting to a new buyer. "It's going to be massive," she's saying. "MASSIVE." Behind her, a young man with paint on his trainers and a backpack is edging closer to the buyer's handbag. He has very fast hands.`,
        text: `Watch the private swap. The kid owns up when shown the photos. The contested oil painting is a physical prop.`,
        checks: [['mov', 'medium', `Get behind Sam before he reaches the handbag`, `Your hand on his shoulder. He freezes.`, `He's done it. The painting's in his backpack.`],
          ['aim', 'medium', `Photograph the swap as it happens, from across the bar`, `Sharp: Sam's hand, the painting, the bag.`, `Blurred.`],
          ['whl', 'medium', `If Sam bolts on his bike, follow him home`, `He leads you to Essex Dry Goods. Grace's warehouse.`, `He's gone down the canal.`]]},
      {at: 'DB4.2', title: `Settling it at The De Beauvoir Arms`, read: `The function room at The De Beauvoir Arms. Grace Okafor sits at a table in her warehouse fleece. Sam sits beside her, embarrassed. The buyer sits opposite, and Viv Shore at the end, looking at the door. Grace takes the painting and looks at it for a long time. "My husband painted this," she says. "The arches on Morning Lane. That's Pat in the headscarf."`,
        text: `Settle all the claims. The dealer brings a new buyer to the dinner.`,
        checks: [['frt', 'medium', `Broker a fair settlement between the buyer and Grace's family`, `The buyer gets her money back. Grace keeps the painting.`, `The buyer insists on her rights.`],
          ['mus', 'easy', `Carry Grace's heavy chair into the function room so she can sit at the head of the table`, `She sits. She nods at you.`, `It scrapes. She gives you a look.`]]}
    ],
    closeTitle: `Read aloud: that's Pat`,
    close: `Grace Okafor props the painting on the table so everyone can see it: the arches, the bicycle, the woman in the headscarf. "My Joseph painted it in 1976," she says. "Pat was twenty-five. She'd just opened the shop." She smiles. "He gave it to me for our first anniversary." She looks at Sam. "My grandson keeps taking it back because his mother sold it when I wasn't looking." Sam looks at his trainers. Grace pats his hand. "Good boy," she says.`,
    notes: [`The decision: sell it with the honest history, return it to the family, expose the dealer, or pocket the dodgy profit.`,
      `The contested oil painting is a physical prop.`,
      `Reward: £160 and 1 GE or RT Renown once. A regular viewing contact depends on what the buyer was told.`,
      `If the crew show the painting to Pat, she cries. Let her.`]
  },
  s12: {
    brief: `A wedding DJ has lost a one-of-a-kind dedication record. Leon from Dead Air has heard someone selling it as a rare commercial pressing. The wedding is on Saturday, and the bride's nan recorded the dedication. What's really going on: a record broker grabbed the wrong sleeve, then kept the disc because it looked valuable. It's private family stuff, nothing to do with Nia. The twist: the bride's nan was a Dead Air DJ in the 80s. Leon trained under her.`,
    openTitle: `Read aloud: wedding's Saturday`,
    open: `The wedding DJ is close to tears. "Lost a one-off recording. A dubplate. A dedication for a wedding. The bride's nan recorded it." He holds up an empty sleeve. "This is the sleeve. The record's gone." His phone buzzes. "Leon from Dead Air says someone's selling it as some rare release." He puts his head in his hands. "Wedding's Saturday. Help!"`,
    cast: ['polly-james', 'toby-lin', 'leon-marsh'],
    people: {'nan-ivy': {name: 'Ivy "Lady Ice" Campbell', role: 'The bride\'s nan, a Dead Air DJ in the 80s', img: PED(16), look: 'Eighties, a velvet tracksuit, gold hoops, a walking stick with stickers on it.', manner: 'Mischievous, fearless, remembers every tune.', wants: 'Her granddaughter\'s wedding to have the right record.', line: 'I was on the air before that boy Leon could hold a fader.'}},
    roles: {'polly-james': `Kiosk attendant at The Prince Arthur. Saw the broker's customer.`, 'toby-lin': `Record dealer at Wilton Way. Has the disc, thinks it's a rare pressing.`, 'leon-marsh': `Heard the disc offered. Will know it when he hears it.`, 'nan-ivy': `The bride's nan.`},
    scenes: [
      {at: 'LF2.2', title: `The Prince Arthur, the saloon`, read: `The saloon at The Prince Arthur. Polly James, behind the hatch with her nose ring, polishes a glass. "Record bloke?" she says. "Yeah. Came in Tuesday. Showed a customer a white label. Said it was a rare Lovers Rock pressing. One of five." She leans forward. "Customer said it sounded like an old lady saying 'congratulations' over a bassline." She laughs. "He bought it anyway."`,
        text: `The broker's customer. He bought it for £200 and sold it on to Toby Lin.`,
        checks: [['frt', 'medium', `Get Polly to tell you who the customer sold it to`, `"Toby Lin. Wilton Way. He collects white labels."`, `"I didn't see nothing. Well. I saw a record."`],
          ['grt', 'easy', `Wait at the bar until the customer comes back for his regular Tuesday pint`, `He comes in at nine. He's sheepish. "Sold it to Toby."`, `You leave at eight.`]]},
      {at: 'LF6.3', title: `The Wilton Way Deli, the back table`, read: `Toby Lin at the back table of the Wilton Way Deli, his crate on wheels beside him, holding a white label up to the light. "One of five," he says. "Lovers Rock, 1984. I'd sell my nan for it." He grins. "Don't tell my nan." You tell him what it really is. His grin fades. "A wedding dedication? Seriously?"`,
        text: `The sleeve swap. Toby thought he'd bought a rarity. The wedding dubplate is a physical prop.`,
        checks: [['grf', 'medium', `Swap the disc into its proper sleeve without Toby noticing (he won't give it up willingly)`, `Swapped. He's holding an empty sleeve.`, `He notices.`],
          ['mus', 'easy', `Lift Toby's heavy crate down the deli steps for him, to soften him up`, `He softens. "Fine. What's it worth to the bride?"`, `You drop a corner. He winces.`]]},
      {at: 'LF8.2', title: `The Englefield Listening Flat`, read: `Leon Marsh's front listening room. He lowers the needle onto the dubplate. A bassline, warm and slow, and then a woman's voice, older, with a laugh in it: "This one's for my granddaughter, on her wedding day. From Lady Ice, on Dead Air, where I belong." Leon stops it. He has tears in his eyes. "Lady Ice," he says. "She taught me everything. 1984. I was fourteen."`,
        text: `Play the surviving copy. Getting the disc back and having something to play at the wedding are separate wins.`,
        checks: [['aim', 'medium', `Drop the needle exactly on the start groove of the old acetate without scratching it`, `Perfect. The bassline rolls.`, `A tiny scratch at the start. It still plays.`],
          ['whl', 'medium', `Get the record to the wedding venue before the first dance`, `In the DJ's hands as the couple walk onto the floor.`, `The first dance starts without it.`],
          ['mov', 'easy', `Get past the wedding's door staff without an invitation`, `In through the kitchen.`, `They stop you at the door.`]]}
    ],
    closeTitle: `Read aloud: Lady Ice`,
    close: `At the wedding, the DJ drops the needle. The bassline rolls through the hall. "This one's for my granddaughter, on her wedding day. From Lady Ice, on Dead Air, where I belong." In the front row, a woman in her eighties in a velvet tracksuit and gold hoops throws her walking stick in the air. Everyone cheers. Leon, at the back, wipes his eyes. "She was on the air before I could hold a fader," he says.`,
    notes: [`The decision: buy it, steal it, swap for it, or make an agreed replacement from the family copy.`,
      `The wedding dubplate record is a physical prop.`,
      `Reward: £120 and 1 AD or NM Renown once. Leon offers the crew listening slots on agreed terms.`,
      `Lady Ice is a great NPC. Bring her back for AD8 if the crew liked her.`]
  },
  s13: {
    brief: `There's a poster up on Well Street advertising Big Sal in a prize fight he never signed up for. Tickets are already sold. Sal is not happy. Nobody wants Sal not happy. What's really going on: Sal's rival forged the booking to embarrass him and pocket the deposits. A second fighter genuinely needs the money and might take a proper, above-board replacement bout. The twist: the rival was paid by the same middleman who's been printing fake "Stretch" letters.`,
    openTitle: `Read aloud: before I sort it myself`,
    open: `Big Sal stands outside Chicken Palace holding a torn poster. It says: "WELL STREET SMOKER — BIG SAL vs. THE HAMMER — PRIZE FIGHT — £20 ON THE DOOR". There's a photo of Sal on it, from a wedding. "Sal here," he says, unnecessarily. "There's a poster on Well Street. Says I'm fighting some geezer for prize money." He folds it very carefully. "I never agreed to nothing. And they've already sold tickets." He looks at you. "Sort it before I sort it myself."`,
    cast: ['big-sal', 'daniel-firth', 'salma-dean', 'kez'],
    people: {'the-hammer': {name: 'Tony "The Hammer" Rossi', role: 'Sal\'s rival, who forged the booking', img: PED(10), look: 'Forties, broken nose, gold chain, a tracksuit two sizes too small.', manner: 'All mouth, no trousers.', wants: 'The deposits and to see Sal embarrassed.', line: 'He\'s scared. Everyone knows he\'s scared.'}, 'kofi': {name: 'Kofi Mensah', role: 'The second fighter, who needs the money', img: PED(21), look: 'Twenties, gym bag, taped hands, a quiet face.', manner: 'Polite, serious, honest about needing the purse.', wants: 'A fair fight and a fair purse to pay his mum\'s rent.', line: 'I\'ll fight anyone. Properly. With a ref.'}},
    roles: {'big-sal': `Says little, means all of it. Furious and trying not to be.`, 'daniel-firth': `Committee clerk at The Gun who keeps the boxing club's minutes.`, 'salma-dean': `Printed the poster, and the order number on the back.`, kez: `Saw the poster first and ran to tell Sal.`, 'the-hammer': `The rival who forged the booking.`, kofi: `The second fighter who needs the money.`},
    scenes: [
      {at: 'WS3.3', title: `The rival at The Gun`, read: `The back room at The Gun on Well Street. A man with a broken nose and a tracksuit two sizes too small sits with his mates. "He's scared," Tony Rossi says loudly as you come in. "Everyone knows Sal's scared." Daniel Firth, the club clerk, sits in the corner with a minute book. "I'm afraid there's no record of Mr Sal agreeing to anything," he says. "I'd have minuted it."`,
        text: `The rival, all mouth. Daniel's minutes show there was no booking.`,
        checks: [['mus', 'medium', `When Rossi gets in your face, don't move an inch`, `He bounces off your chest. His mates laugh at him.`, `He shoves you back a step. His mates cheer.`],
          ['grt', 'easy', `Sit through Daniel reading the last six months of club minutes to prove there was no booking`, `Six months. No booking. Daniel is thrilled to be useful.`, `You stop him at month three.`]]},
      {at: 'WS7.3', title: `The Wickside Print Shop`, read: `The proof table at the Wickside Print Shop. Salma Dean holds up the amended proof: the original poster said "EXHIBITION BOUT — TBC". Someone paid to change it to "BIG SAL". "Same account as the Stretch letters," she says. "Lark Holdings." She turns the proof over. "And I printed the order number on the back."`,
        text: `The amended promotional print proof is a physical prop.`,
        checks: [['sav', 'medium', `Recognise the account from the Stretch letters (NM4)`, `Lark Holdings. Of course.`, `It's just a company.`],
          ['grf', 'medium', `Copy the order file while Salma's boss is on the print floor`, `On a USB stick.`, `The boss comes back.`]]},
      {at: 'WS4.3', title: `The cash handover at The Lauriston`, read: `The function room at The Lauriston, weigh-in night. Forty people are here for the fight, with tickets. Tony Rossi stands at a table counting the door money. In the corner, a quiet young man with a gym bag and taped hands sits on a chair. "I'm Kofi," he says. "I was told I'm the undercard. I need the purse. My mum's rent." Big Sal walks in. The room goes silent.`,
        text: `The cash handover. Sal makes his own choice: fight, refuse, or promote something fairer.`,
        checks: [['btl', 'medium', `Stand with Sal in front of forty people while he decides`, `Sal looks at you, then at the room. He speaks.`, `You look at the floor. Sal decides alone.`],
          ['aim', 'medium', `When Rossi grabs the cash box and runs, hit him with a thrown boxing glove`, `It catches him on the back of the head. He drops the box.`, `It hits the ref.`],
          ['whl', 'medium', `If he gets to his car with the money, cut him off on Lauriston Road`, `Boxed in. He hands it over.`, `He's gone.`]]}
    ],
    closeTitle: `Read aloud: Sal decides`,
    close: `Big Sal stands in the middle of the function room, rings on every finger, and looks at Kofi. "You need the purse?" he says. Kofi nods. Sal turns to the room. "Then here's what happens. Kofi fights an exhibition. Three rounds. With a ref. Against whoever wants it." He looks at Rossi, who has gone very pale. "And the door money goes to Kofi's mum." He turns back to you. "You want me to have a word with Rossi?" he says. "I'll have a word."`,
    notes: [`The decision: get the deposits back, stage a fair alternative, or grab the fraudster's takings. Sal makes his own choice.`,
      `The amended promotional print proof is a physical prop.`,
      `Reward: £160 and 1 CH or BB Renown once. Sal's public choice makes a sporting ally or a rival who keeps turning up.`,
      `Kofi is a good recurring NPC: a hire candidate later?`]
  },
  s14: {
    brief: `A passenger paid two different couriers to deliver the same locked record case. Both couriers want Tern on their side, and neither knows they've been double-booked. What's really going on: the passenger set up two deliveries that can't both happen, to hide a private sale from a business partner. The case is full of valuable records, not a master tape. The twist: the business partner being cheated is Pearl Okonkwo.`,
    openTitle: `Read aloud: paid twice`,
    open: `Tern on the radio. "Tern. Got a passenger who paid two couriers for one record case." Postcodes crackle in the background. "Both couriers want me to back them." She sighs. "Neither knows about the other. Untangle it before they find out. Over."`,
    cast: ['mara-boyd', 'indira-shaw', 'alix-porter', 'eileen-grant'],
    people: {'pearl-okonkwo': {}},
    roles: {'mara-boyd': `Tern. Wants her couriers protected.`, 'indira-shaw': `Workshop manager on Barge East. One courier delivers to her workshop.`, 'alix-porter': `Stores keeper at the People's Park Tavern. Has the second receipt.`, 'eileen-grant': `At Grow Hackney, where the sale meeting happens.`, 'pearl-okonkwo': `Off stage. The business partner being cheated.`},
    scenes: [
      {at: 'VW1.1', title: `The first courier aboard Barge East`, read: `The deck saloon of Barge East, moored on the Lea. A courier in a cycling jacket sits with a locked record case at his feet and a delivery note. "Pick up from the market, deliver to the workshop," he says. Indira Shaw, in her workshop apron, nods. "That's for me. A sale. Fifty records." She looks at the case. "But I've already been told it's going somewhere else."`,
        text: `The first courier. His delivery note says Indira's workshop.`,
        checks: [['grf', 'medium', `Pick the case's lock to see what's inside, without leaving a mark`, `Fifty rare records. A Night Market stock sticker on every sleeve.`, `It won't open.`]]},
      {at: 'VW6.2', title: `The People's Park Tavern, the bar`, read: `The bar at the People's Park Tavern. Alix Porter, keyring like a fist, holds up a receipt. "Second courier," she says. "Same case. Same pick-up. Delivery to Grow Hackney. Tonight." She checks her book. "If it isn't in the book, it never left. It's in the book twice. That's a problem."`,
        text: `The second receipt. Same case, different destination. The double-paid passenger receipt is a physical prop.`,
        checks: [['sav', 'medium', `Compare the two receipts and work out the passenger's plan`, `One delivery is cover for the other. He wants a record of sending it to Indira, while really selling it at Grow Hackney.`, `It's a mix-up to you.`],
          ['grt', 'easy', `Wait with Alix through her stock count until she shows you the passenger's name`, `"P. Adebayo." Pearl's business partner.`, `You leave early.`]]},
      {at: 'VW4.4', title: `The sale meeting at Grow Hackney`, read: `A greenhouse at Grow Hackney, fairy lights and tomato plants. Eileen Grant is here for an arts night. In the corner, the passenger, a man in a smart jacket, is counting cash from a buyer. Both couriers are outside, arguing with each other about who's got the case. The buyer pays while they argue.`,
        text: `The buyer pays while both couriers are still arguing. The passenger can walk off with the money; chase it or rework the delivery.`,
        checks: [['mov', 'medium', `Slip past the arguing couriers and get to the passenger before he leaves`, `You're in front of him as he turns.`, `He's out the back.`],
          ['whl', 'medium', `If he drives off, chase him through Hackney Wick`, `Boxed in by the canal.`, `Lost in the one-way streets.`],
          ['aim', 'medium', `Knock the cash envelope out of his hand with a thrown flowerpot`, `Splat. Soil and fifties everywhere.`, `It hits a tomato plant.`],
          ['mus', 'easy', `Carry the heavy record case back to Tern's van`, `Done.`, `It slips. A record cracks.`]]}
    ],
    closeTitle: `Read aloud: Pearl's records`,
    close: `Pearl Okonkwo opens the record case on her stall at the Night Market, and goes through it sleeve by sleeve. Every one has her stock sticker. "Fifty records," she says. "My stock. My business partner." She closes the case. "Everybody eats on my market," she says. "Even the ones I don't like." She looks up. "But he's going to eat somewhere else from now on." Tern, beside you, laughs out loud.`,
    notes: [`The decision: complete one contract out in the open, split compensation, or buy the records.`,
      `The double-paid passenger receipt is a physical prop.`,
      `Reward: £160 and 1 TU or NM Renown once. The courier the crew back offers transport later at normal rates.`,
      `Pearl being cheated is a nice link to NM.`]
  },
  s15: {
    brief: `A performer's lucky jacket has vanished, with a small inheritance and the first-night cue tucked in the pocket. A rival is strutting about in an identical one, swearing it's theirs. What's really going on: a wardrobe assistant mixed up the jackets during a private costume session. A guest pinched the envelope afterwards and is trying to spend it at another event. The twist: the guest is Celia Voss's nephew. She'll pay a lot for this to stay quiet.`,
    openTitle: `Read aloud: my lucky jacket`,
    open: `The performer rings from a dressing room, and you can hear someone doing vocal warm-ups in the background. "My lucky jacket's gone. Red velvet. My nan's." A pause. "With my inheritance in the pocket. Two thousand pounds. And my first-night cue card." Another pause. "Some rival's wearing one EXACTLY like it and swears it's theirs." A wail from the warm-up next door. "Help."`,
    cast: ['maya-foster', 'jules-akin', 'ada-march'],
    people: {'jasper-voss': {name: 'Jasper Voss-Hale', role: 'Celia Voss\'s nephew, who took the envelope', img: PED(1), look: 'Twenties, expensive trainers, a cashmere jumper, a fat wallet that isn\'t his.', manner: 'Entitled, charming, crumbles when caught.', wants: 'A good night out on someone else\'s money.', line: 'It was just lying there. Finders keepers?'}, 'celia-voss': {}},
    roles: {'maya-foster': `Personal shopper at the Westfield costume stand. Saw the jackets mixed up.`, 'jules-akin': `Patch. At the V&A East workshop event. Spotted someone flashing cash.`, 'ada-march': `"Index." Recognises the nephew from her cards.`, 'jasper-voss': `Took the envelope.`, 'celia-voss': `Off stage. Will pay to keep it quiet.`},
    scenes: [
      {at: 'ST1.3', title: `The costume stand at Westfield`, read: `A temporary costume stand at Westfield Stratford City: rails of jackets, mirrors, a fitting booth. Maya Foster, in a designer coat, carrying bags that aren't hers, nods at two red velvet jackets on a rail. "Private session on Tuesday," she says. "Two performers. Two identical jackets. The assistant mixed them up." She shrugs. "I don't ask. I just carry the bags."`,
        text: `The temporary costume stand. Two identical jackets were mixed up. The inherited stage jacket is a physical prop.`,
        checks: [['sav', 'medium', `Tell the two jackets apart`, `One has a nan's initials stitched inside the collar: "M.R. 1962". That's the lucky one.`, `They look identical.`],
          ['grf', 'easy', `Check the inside pocket without the rival noticing`, `Empty. The envelope's gone. But the cue card's still there.`, `The rival catches you.`]]},
      {at: 'ST4.5', title: `Theatre Royal Stratford East, wardrobe`, read: `The wardrobe at Theatre Royal Stratford East: rails, sewing machines, a smell of steam and starch. The rival performer stands in front of a mirror in the red velvet jacket. "It's mine," she says. "I bought it in Camden." She turns round. "Look, it fits me perfectly." It doesn't.`,
        text: `Compare the jackets. The rival is honestly mistaken. The envelope was taken by a guest after the session.`,
        checks: [['frt', 'medium', `Persuade the rival to check the collar of the jacket she's wearing`, `She checks. "M.R. 1962." She takes it off. "Oh. Sorry."`, `She refuses.`],
          ['grt', 'easy', `Help the wardrobe team steam every costume for tonight so they'll tell you who was at the session`, `"A posh lad. Cashmere jumper. Kept asking about the jackets."`, `They're too busy to talk.`]]},
      {at: 'ST6.4', title: `The V&A East workshop`, read: `The preparation studio at V&A East, a "young patrons" workshop. Patch from Dead Air waves you over. "Posh lad, cashmere jumper," he whispers. "Been buying rounds all night. Fifties." Across the room, a young man in expensive trainers is laughing loudly, with a fat envelope sticking out of his back pocket. Ada March, beside Patch, has an index card in her hand. "Jasper Voss-Hale," she says. "Celia's nephew."`,
        text: `The guest, flashing cash. The cue can be rebuilt even if the money is gone. Curtain up is after the second appointment.`,
        checks: [['grf', 'hard', `Lift the envelope from his back pocket`, `It's in your hand. Two thousand, minus four hundred spent.`, `He feels it.`],
          ['mov', 'medium', `Catch him when he bolts for the courier court`, `You catch his cashmere sleeve.`, `He's in a taxi.`],
          ['aim', 'medium', `Toss the performer her jacket from the wings as she walks on stage`, `Caught, on, curtain up.`, `It lands on a stagehand.`],
          ['whl', 'medium', `Get from Stratford to the theatre with the jacket before curtain up`, `In the wings as the lights go down.`, `Curtain up without it.`]]}
    ],
    closeTitle: `Read aloud: her nan's jacket`,
    close: `The performer walks onto the stage at Theatre Royal Stratford East in a red velvet jacket with "M.R. 1962" stitched inside the collar. In the wings, she pats the pocket: the cue card, and an envelope with sixteen hundred pounds in it. Later, at the stage door, a smartly dressed woman's assistant appears beside you with a cream envelope. "Mrs Voss would be grateful," she says, "if her nephew's name didn't come up." The envelope is very thick.`,
    notes: [`The decision: get the inheritance back, negotiate repayment, or sort a replacement costume and a debt.`,
      `The inherited stage jacket is a physical prop.`,
      `Reward: £160 and 1 VC or GE Renown once. The performer invites the crew backstage for future work.`,
      `Celia's hush money is a temptation. Whatever they do, it's leverage one way or another.`]
  },
  s16: {
    brief: `A family wants their cabinet back before a lender sells the contents. Frankie Wu says it was handed over to settle a debt. The family says there was only ever one loan, and it was nearly paid. What's really going on: the cabinet was offered against one real loan. A second collector invented another debt. A locked drawer holds a family photo and an unrelated valuable watch. The twist: the watch belongs to Rob Kinsella, the missing East Cross driver from NM3. It's been in the drawer the whole time.`,
    openTitle: `Read aloud: one loan`,
    open: `The family sits round their kitchen table: a mother, a father, a teenage son. The space by the wall where a cabinet used to stand is a clean rectangle on the wallpaper. "We want our cabinet back," the mother says. "Frankie says we handed it over to clear a debt." She shakes her head. "We only ever had ONE loan. And we nearly paid it." She holds up a stack of payment slips. "The lender's about to sell what's inside. Help us."`,
    cast: ['gita-mercer', 'eddie-lane', 'frankie-wu'],
    roles: {'gita-mercer': `The family's neighbour. Helped them move the cabinet out. Saw the second collector.`, 'eddie-lane': `Cashier at the Coin Rooms. Knows which debts are real.`, 'frankie-wu': `The accountant. Wins or loses one family's trust.`},
    scenes: [
      {at: 'HX1.2', title: `The Wenlock Arms, the snug`, read: `The snug at The Wenlock Arms. The family sits with Gita Mercer, their neighbour, in her stores coat. "Two men came with a van," Gita says. "One had real paperwork. The other had a clipboard and a lot of chat." She holds up a business card. "This one. 'Debt Recovery Solutions.' Never heard of them."`,
        text: `The family. Gita saw the second collector.`,
        checks: [['frt', 'medium', `Get the family to show you every payment slip and tell you every detail`, `One loan, £800, £640 paid. The second "debt" is invented.`, `They're too upset to go through it.`],
          ['mus', 'easy', `Help Gita carry the family's shopping up four flights while you talk`, `She tells you the van's plate.`, `You drop the eggs.`]]},
      {at: 'HX3.5', title: `The second collector at the Rosemary Branch`, read: `The Rosemary Branch Theatre's dressing room has been hired for a private booking: the second collector is using it as an office. A man with a clipboard sits among the costume rails, counting cash. "Debt recovery," he says. "Legitimate business." On a chair beside him: the family's cabinet, its locked drawer facing the wall.`,
        text: `The second collector. The cabinet is here. The resale is booked after the third meeting.`,
        checks: [['grf', 'hard', `Pick the cabinet's locked drawer while he's on the phone`, `Inside: a family photo, and a gold watch engraved "To R. from Mum, 2002".`, `The lock's stiff. He turns round.`],
          ['mov', 'medium', `Get out down the fire escape with the drawer's contents before he sees`, `Down and away.`, `The fire escape's locked.`]]},
      {at: 'HX8.3', title: `The Shepherdess Coin Rooms, account office`, read: `The account office at the Shepherdess Coin Rooms. Frankie Wu sits with two laptops. Eddie Lane hovers in the doorway. "The real account," Frankie says. "One loan. £800. They've paid £640." She turns the laptop. "The second debt doesn't exist. Someone made it up." Eddie clears his throat. "That one's real. That one isn't. Don't tell Vic I told you."`,
        text: `The real account. Show the family the watch and they'll name its owner.`,
        checks: [['sav', 'medium', `Recognise the watch's engraving`, `"To R. from Mum, 2002." Rob Kinsella's. The missing driver from NM3.`, `It's just a watch to you.`],
          ['whl', 'medium', `Get the cabinet back before the resale van collects it`, `Loaded into your van as theirs pulls up.`, `Theirs leaves first.`],
          ['aim', 'medium', `Photograph the second collector's van as it pulls away, plate clear`, `Registered to East Cross Security.`, `Blurred.`]]}
    ],
    closeTitle: `Read aloud: in the drawer the whole time`,
    close: `The family's cabinet stands back against the wall, in its clean rectangle. The mother opens the locked drawer and takes out the family photo: her own parents, on their wedding day. Then she takes out the watch and turns it over. "This isn't ours," she says. "Rob's. The lad from upstairs." She looks at you. "He left it here for safekeeping, in March. Said someone was after him." She puts it in your hand. "He never came back for it."`,
    notes: [`The decision: return the whole cabinet, pay off the real debt, or sell the watch with the owner's say-so.`,
      `The family watch from the disputed cabinet is a physical prop.`,
      `Reward: £160 and 1 BB or NM Renown once. Frankie wins or loses one family's trust.`,
      `Rob Kinsella left the watch here. That's a big clue for RT and LD4.`]
  },
  s17: {
    brief: `Someone has made off with the prize money for Kez's bike-riding contest. A rival rider is getting the blame because they had a row about the route. Jaz or Femi can make this one personal. What's really going on: an organiser lent the fund to a mate for a rushed business idea. The accused rider is innocent; they just argued about the route. The twist: the "rushed business" is a bike courier firm. Tern is already thinking of buying it.`,
    openTitle: `Read aloud: Kez's contest`,
    open: `Kez rings, out of breath, on his BMX. "Kez here. Some muppet's nicked the prize fund for my riding contest." You can hear him braking. "Three hundred quid. For the kids." A pause. "Everyone's blaming Jaz because she had a row about the route. It weren't her." Another pause. "Find the money and save the contest. Please. The kids have been practising for a month."`,
    cast: ['kez', 'sylvie-ward', 'amina-keane'],
    people: {jaz: {name: 'Jaz', role: 'Young rider being blamed', img: 'systems/the-smoke/assets/tokens/people/npc-jaz.webp', look: 'Eighteen, BMX helmet with stickers, scabbed knees, a route map drawn on her arm in biro.', manner: 'Fierce, honest, furious at being blamed.', wants: 'Her name cleared and a fair route.', line: 'I said the route was dangerous. That\'s not stealing. That\'s being right.'}},
    roles: {kez: `Runs the contest. Feels responsible.`, 'sylvie-ward': `Shopkeeper at Signature Brew's taproom. Saw the organiser hand over the money.`, 'amina-keane': `Equipment-hire owner. Lent the contest its ramps and cones, and wants paying.`, jaz: `The rider being blamed.`},
    scenes: [
      {at: 'HR3.1', title: `Signature Brew Haggerston, the taproom`, read: `The taproom at Signature Brew, in a railway arch. Sylvie Ward, in her shopkeeper's tabard and bifocals, sips a half. "Your organiser?" she says. "Bloke with a clipboard. Sat right there on Monday and handed an envelope to a mate. 'Just till Friday,' he said. 'For the business.'" She sips. "I know every face on this road. His mate's is new."`,
        text: `The visiting organiser lent the fund to a mate.`,
        checks: [['frt', 'medium', `Get Sylvie to tell you what the "business" is`, `"Bike couriers. Said he's starting a firm."`, `"I know every face. I don't know every business."`],
          ['aim', 'easy', `Win a round of the taproom's beer-mat flipping game to get Sylvie chatting`, `Five mats, one flip. Sylvie laughs and tells you everything.`, `They go everywhere. She laughs anyway.`]]},
      {at: 'HR4.3', title: `Haggerston Community Centre, the meeting room`, read: `The meeting room at Haggerston Community Centre: entry forms on a table, twenty kids' names. Jaz, eighteen, with a BMX helmet and a route map drawn on her arm in biro, sits with her arms folded. "I said the route was dangerous," she says. "Across Queensbridge Road with no marshals. That's not stealing. That's being right."`,
        text: `Compare the entries. Jaz is innocent. The prize entry envelope is a physical prop: the organiser's float, with an IOU in it.`,
        checks: [['sav', 'medium', `Find the IOU among the entry forms`, `"IOU £300 — back Friday — D." Signed by the organiser.`, `Lost in twenty forms.`],
          ['grt', 'easy', `Walk Jaz's route with her to see if she's right about the danger`, `She's right. You redraw it together.`, `You give up halfway.`]]},
      {at: 'HR8.3', title: `The Goldsmiths Riding Workshop`, read: `The practice hall at the Goldsmiths Riding Workshop. Twenty kids on bikes, helmets on, waiting. Cones and ramps from Amina Keane's hire store. The organiser's mate arrives late with an envelope: "Two hundred. I'll have the rest next week." Amina Keane stands by the door with her arms folded. "Hire's per day, darling," she says. "Not per mood."`,
        text: `Run the contest, or the recovery meeting. The mate's repayment lands too late for the start unless someone fronts a temporary prize.`,
        checks: [['whl', 'medium', `Ride the course yourself first to show the kids it's safe`, `Clean round. The kids cheer.`, `You come off on the second ramp. The kids cheer louder.`],
          ['mus', 'medium', `Set up the ramps and cones on Jaz's safer route in twenty minutes`, `Done. The contest starts on time.`, `Late. The kids are restless.`],
          ['mov', 'medium', `Catch the organiser's mate when he tries to slip out the back`, `You've got his sleeve.`, `He's out.`]]}
    ],
    closeTitle: `Read aloud: being right`,
    close: `The contest runs on Jaz's route. A ten-year-old wins on a bike held together with gaffer tape, and screams so loudly the pigeons leave. Jaz hands her the envelope. Kez stands at the side, beaming. Later, Tern rings: "That courier firm the organiser's mate is starting? I'm buying it." She laughs. "Tell Kez he's got a job if he wants one. Over."`,
    notes: [`The decision: recover the money, lend a documented replacement prize, or call it off honestly.`,
      `The prize entry envelope is a physical prop.`,
      `Reward: £120 and 1 CH or BM Renown once. A regular workshop role takes time and an agreed contribution.`,
      `If a PC has Jaz or Femi as a contact, make it personal.`]
  },
  s18: {
    brief: `Arthur Venn, retired cabbie, has heard there's a memorial benefit planned in his honour. He's very much alive and wants to know who's pocketing the donations. He's also quite keen on making an entrance. What's really going on: a former colleague invented Arthur's death to pay off a gambling debt. A visiting promoter swallowed the story and booked a very odd evening programme. The twist: the gambling debt is owed to Vic Randle. Vic is coming to the benefit. He's bringing flowers.`,
    openTitle: `Read aloud: I'm not dead, son`,
    open: `Arthur Venn sits in his flat in Bethnal Green in a flat cap with a Thermos of sweet tea. He holds up a flyer: "IN MEMORY OF ARTHUR VENN, 1951–2026. A BENEFIT NIGHT. ALL DONATIONS TO THE FAMILY." He taps his own face on it. "Arthur Venn," he says. "Drove a black cab forty years." He puts the flyer down. "I'm not dead, son." He sips his tea. "So who's collecting the money?"`,
    cast: ['arthur-venn', 'lena-morris', 'otis-mensah', 'iris-bellamy'],
    people: {'victor-randle': {}},
    roles: {'arthur-venn': `Very much alive. Talks in routes. Wants to make an entrance.`, 'lena-morris': `Volunteer clinician at St John on Bethnal Green. Signed nothing, because there was nothing to sign.`, 'otis-mensah': `Minicab dispatcher at the Viktor Wynd Museum gathering. Knew Arthur's old colleague.`, 'iris-bellamy': `At Bethnal Green Library. Can compare the "obituary" with the real club newsletter.`, 'victor-randle': `Owed the gambling debt. Coming to the benefit with flowers.`},
    scenes: [
      {at: 'BG4.3', title: `St John on Bethnal Green, the hall`, read: `The hall at St John on Bethnal Green, being set up for the benefit: a photo of Arthur on an easel, a collection bucket, a table of sandwiches. A booking volunteer with a clipboard looks up, sees Arthur behind you, and drops the clipboard. Dr Lena Morris, the volunteer clinician who uses the hall for a clinic, raises an eyebrow. "I can tell you what's wrong with him," she says. "Nothing. He's fine."`,
        text: `Arthur and the booking volunteer. The false funeral booking record is a physical prop.`,
        checks: [['frt', 'medium', `Calm the booking volunteer down enough to show you the booking`, `"Booked by a Mr Doyle. Said he was Arthur's oldest friend." She shows you the form.`, `She's too shocked to speak.`],
          ['grt', 'easy', `Listen to Arthur's whole story about every fare he ever drove`, `He mentions "Gerry Doyle, owed half of Hackney".`, `You stop him at 1983.`]]},
      {at: 'BG6.3', title: `The Viktor Wynd Museum gathering`, read: `The Viktor Wynd Museum of Curiosities: a basement full of skulls, stuffed animals and two-headed lambs in jars. Tonight, a "gathering" for the benefit's sponsors. A visiting promoter in a velvet cape is explaining the evening's programme: a tribute act, a magician, a medium who will "contact Arthur". Otis Mensah, a minicab dispatcher in a cardigan, nearly chokes on his drink.`,
        text: `The promoter, among the curiosities. He swallowed the story completely. Otis knew Gerry Doyle.`,
        checks: [['mov', 'medium', `Weave through the cramped museum to the promoter without knocking over a two-headed lamb`, `You arrive beside him. Nothing broken.`, `A jar wobbles. Everyone gasps.`],
          ['aim', 'easy', `Photograph the medium's "contact Arthur" poster across the room for Arthur to see`, `Arthur laughs so hard he has to sit down.`, `Blurred.`]]},
      {at: 'BG5.4', title: `Bethnal Green Library, local studies`, read: `The local history room at Bethnal Green Library. Iris Bellamy in white gloves lays two papers side by side: the "obituary" handed round at the benefit, and the real cab drivers' club newsletter from last month. "The obituary says he died in March," she says. "The newsletter says he won the club's darts in April." She looks at Arthur over her glasses. "Congratulations."`,
        text: `The "obituary" against the real club newsletter. Arthur decides how loudly to come back from the dead.`,
        checks: [['sav', 'medium', `Spot who wrote the obituary from the details it gets wrong`, `It calls Arthur's late wife "Jean". Her name was Joan. Only Gerry ever got it wrong.`, `It all seems accurate.`]]},
      {at: 'BG4.2', title: `The benefit night`, read: `The benefit night. The hall is full. The tribute act is singing "My Way". At the interval, a man in a cheap suit, Gerry Doyle, goes to collect the bucket. Then the door opens and a man in a camel coat walks in carrying an enormous wreath of lilies: Vic Randle. He stops. Because Arthur Venn is standing in the middle of the hall in his flat cap, very much alive.`,
        text: `The debtor collects the cash at the interval: a public showdown, or a chase later.`,
        checks: [['whl', 'medium', `If Gerry runs with the bucket, catch his car on Cambridge Heath Road`, `Boxed in at the lights.`, `He's gone.`],
          ['mus', 'easy', `Take the collection bucket off Gerry before he reaches the door`, `Bucket in your hands.`, `He's out with it.`],
          ['btl', 'medium', `Stand between Vic and Gerry when Vic realises what's happened`, `Vic looks at you, and puts the wreath down. "Thursday, Gerry," he says. "My office."`, `Vic's men take Gerry outside.`]]}
    ],
    closeTitle: `Read aloud: an entrance`,
    close: `Arthur Venn walks to the front of the hall, takes the microphone off the tribute singer, and taps it. "Mare Street to Bow in nine minutes," he says. "1983. With a woman in labour in the back." The hall goes silent. "Don't tell me about traffic." He looks at Gerry. "And don't tell me I'm dead." Then he looks at the crowd. "But since you're all here," he says, "let's raise some money for the Mutual. I'm buying." Vic Randle, holding his wreath, starts to laugh.`,
    notes: [`The decision: give the donations back, let Arthur turn it into a proper benefit, or make the debtor pay up. Arthur decides how to reveal he's alive.`,
      `The false funeral booking record is a physical prop.`,
      `Reward: £160 and 1 BM or BB Renown once.`,
      `Vic arriving with flowers is the comic peak. Let it land.`]
  },
  s19: {
    brief: `A valuable stage bell has turned up at the market packed in a crate with stagehand Perry Sloane's bloodstained coat. Perry has been found dead offstage. This isn't a caper: it's a murder, and Pearl wants it treated like one. What's really going on: Len Fisk killed Perry after Perry found out about Len's separate resale fraud. It's a standalone murder: not a Meridian hit, and nothing to do with Nia. The twist: Perry had already posted a copy of Len's second set of books to Pearl. It's sitting in her letterbox at Roman Exchange, unopened.`,
    openTitle: `Read aloud: not a laugh`,
    open: `Pearl doesn't laugh. Not once. "Pearl. This one's not a laugh." Her voice is low and steady. "A stage bell came into the market in a crate. With a coat in it. Bloodstained." A long pause. "Perry Sloane's coat. Stagehand. Lovely boy. Did lights for half the theatres in Bow." Another pause. "They found Perry dead backstage on Tuesday." Her voice doesn't shake. "Find out who did it."`,
    cast: ['pearl-okonkwo', 'riz-sethi', 'ivo-marsh'],
    people: {'len-fisk': {}},
    roles: {'pearl-okonkwo': `Wants it treated as a murder, with care.`, 'riz-sethi': `Yard foreman at the Nunnery Gallery loading bay. Saw the crate and heard the row.`, 'ivo-marsh': `Parcel clerk at Forman's. Scanned the crate in.`, 'len-fisk': `The killer.`},
    scenes: [
      {at: 'OF2.5', title: `The Nunnery Gallery, the loading bay`, read: `The loading bay at the Nunnery Gallery on Bow Road. Riz Sethi, in a hard hat, stands by a stack of empty crates, two radios on his belt, very quiet. "Perry worked here Tuesday," he says. "Lights for the exhibition. Then a man came. Camel coat, rings. They had a row in here. Shouting. About books. Perry said, 'I've sent a copy, Len. It's too late.'" Riz looks at the floor. "Then I went to lunch. When I came back, Perry was gone. So was the bell."`,
        text: `The crate record. A witness remembers the row; no roll is needed for that. Rolls decide speed and what cooperation costs.`,
        checks: [['grt', 'medium', `Go through every crate record for the week with Riz, carefully`, `Crate 14: "Bell, stage, bronze." Signed out by "L. Fisk", 13:10 Tuesday.`, `You find the crate, but not who signed it out.`],
          ['sav', 'medium', `Notice what doesn't fit in the loading bay`, `A scuff on the floor, a missing fire extinguisher, a camel-hair fibre on a nail.`, `You see nothing unusual.`]]},
      {at: 'OF6.3', title: `The private gathering at Forman's`, read: `Forman's on Fish Island, a private gathering in the side gallery. Len Fisk stands in his camel-hair coat over a market tabard, rings on every finger, all smiles, telling a story to a group of traders. "I can shift anything, me," he says. "Anything. Ask anyone." Ivo Marsh, at the door with his scanner, catches your eye. "Every parcel gets scanned," he says quietly. "Every scan gets a time. The crate came through here at 14:02. Len signed for it."`,
        text: `Len Fisk, all smiles. He tries to sell the bell after the second interview. Tip him off and he runs to a buyer listed in his ledger.`,
        checks: [['frt', 'medium', `Talk to Len without letting him know what you know`, `He's relaxed. He mentions a buyer: "Roman Exchange, tonight."`, `He sees something in your face. He goes quiet.`],
          ['aim', 'medium', `Photograph Len's signature on Ivo's scanner screen, from across the room`, `Clear: "L. Fisk, 14:02."`, `Glare.`]]},
      {at: 'OF7.4', title: `Roman Exchange, the back store`, read: `The back store at Roman Exchange, late. A bronze stage bell sits on a trolley, wrapped in a blanket. Len Fisk stands beside it with a buyer, counting cash. Out front, in Pearl's letterbox, unopened, is a thick brown envelope with Perry Sloane's handwriting on it.`,
        text: `Len trying to get rid of the bell. The bell in the disputed crate is a physical prop. Perry's envelope is in Pearl's letterbox.`,
        checks: [['mov', 'medium', `Get to Pearl's letterbox and get Perry's envelope before Len remembers it`, `In your hand. Perry's handwriting: "Pearl — Len's second books. In case."`, `Len's at the door.`],
          ['mus', 'hard', `When Len runs, stop him at the delivery court gate`, `He hits the gate. You hold him there.`, `He shoves past.`],
          ['whl', 'medium', `If Len gets to his car, chase him up Roman Road`, `You box him in by the market. Blue lights behind you: Pearl called Vale.`, `He's gone.`],
          ['btl', 'medium', `Face Len when he turns and threatens you`, `You don't move. He sees it's over.`, `You flinch. He runs.`]]}
    ],
    closeTitle: `Read aloud: Perry's envelope`,
    close: `Pearl sits at her front counter at Roman Exchange with Perry's envelope open in front of her: a photocopied ledger, Len's second set of books, and a note in Perry's handwriting. "Pearl. Len's been selling stock twice. I told him I'd tell you. If anything happens, here it is. P." Pearl reads it three times. She doesn't cry. "Lovely boy," she says. "Did lights for half the theatres in Bow." She folds the note and puts it in her apron. "Everybody eats," she says quietly. "Not Len. Not any more."`,
    notes: [`The decision: get the bell back and decide who hears the truth, sell an honest ownership claim, or cover for the killer at a stated price.`,
      `The bell in the disputed crate is a physical prop.`,
      `Reward: £240 and 1 NM or LD Renown once for the disclosed job. Hide Len and Perry's family become enemies for good.`,
      `This is a murder. Play it straight and with care. No gore; the weight is in Pearl's grief.`,
      `It's standalone: not Meridian, and not connected to Nia.`]
  },
  s20: {
    brief: `A student film shoot accidentally caught a van handover in the background: a performer, Mara Sol, being made to go somewhere she didn't want to. Tern wants her found before one of her drivers carries the can. What's really going on: Harlan Black, a crook working on his own, is forcing Mara to work off a made-up debt. It's separate from the Meridian plot. Mara also wants her friend freed from another debt. The twist: Harlan Black rents his vans from the East Cross compound. Rusk takes a cut of every job.`,
    openTitle: `Read aloud: find her`,
    open: `Tern sends a video: a student film, two actors on the towpath at 3 Mills, and in the background, out of focus, a van. A woman in a sequinned jacket is being steered into it by a man in a wax jacket, his hand on her elbow. She looks back once, straight at the camera. "Student film crew caught something in the back of a shot," Tern says. "A van. A performer called Mara Sol. And a handover she clearly didn't want." A pause. "Find her before one of my drivers gets the blame. Over."`,
    cast: ['mara-boyd', 'riz-sethi', 'nia-bell', 'gita-mercer'],
    people: {'mara-sol': {}, 'harlan-black': {name: 'Harlan Black', role: 'Freelance heavy for hire', img: PED(14), look: 'Fifties, shaved head, wax jacket, a car that smells of air freshener and threats.', manner: 'Polite, slow, completely uninterested in your story.', wants: 'His fee, and no complications.', line: 'I don\'t care who\'s right. I care who\'s paying.'}},
    roles: {'mara-boyd': `Tern. Her van was used. Wants Mara Sol found.`, 'riz-sethi': `Yard foreman at 3 Mills Studios. The film crew are his.`, 'nia-bell': `Knows Mara Sol from the clubs. Worried about her.`, 'gita-mercer': `Stores keeper at Marshgate. Black's next delivery comes through her cage.`, 'mara-sol': `Being forced to work off a made-up debt. Has her own plan.`, 'harlan-black': `Working on his own. Rents his vans from East Cross.`},
    scenes: [
      {at: 'BF4.4', title: `3 Mills Studios, the edit suite`, read: `The edit suite at 3 Mills Studios. Three film students sit round a screen, nervous. Riz Sethi stands behind them in his hard hat. "They want to help," he says. "But it's their footage. Ask them properly." On the screen, frozen: the van, the woman, the man's hand on her elbow, the plate half visible.`,
        text: `Get the filmmakers' permission to watch the rushes. The Marshgate van delivery records are a physical prop (later).`,
        checks: [['frt', 'medium', `Ask the students properly for consent to use their footage`, `They agree. They'll even testify.`, `They're scared and say no.`],
          ['aim', 'medium', `Freeze the frame at exactly the moment the van's plate is visible`, `Frame 2,114. The plate: an East Cross hire van.`, `A frame off. The plate's blurred.`]]},
      {at: 'BF6.2', title: `Pudding Mill Lane DLR, the platform`, read: `Pudding Mill Lane DLR, early evening. Nia Bell waits on the covered concourse, hood up. "I know Mara," she says. "From the clubs. She texted me last night. Just one word: 'Marshgate.'" A van driver in hi-vis sits on a bench nearby, eating a sandwich. "That van?" he says, when you show him the photo. "Harlan Black's. He hires it from East Cross. He does a pickup at Marshgate every Thursday."`,
        text: `The driver, and a station witness who knows Black's next paid stop.`,
        checks: [['mov', 'medium', `Catch the driver before he gets on his train`, `He tells you: "Marshgate, Thursday, nine o'clock."`, `The train doors close.`],
          ['grt', 'easy', `Wait with Nia on the cold platform until Mara texts again`, `At 7.40: "Help. Load cage."`, `You leave. You miss it.`]]},
      {at: 'BF7.5', title: `The Marshgate Delivery Depot, the load cage`, read: `The load cage at Marshgate, nine o'clock. Gita Mercer stands at the cage with her clipboard. "Nothing leaves my cage without a signature," she says, very loudly, as a man in a wax jacket walks up with a van behind him. Inside the cage, sitting on a crate, a woman in a sequinned jacket looks up. Mara Sol. "He owns the contract," she says to you. "He doesn't own me."`,
        text: `Black's delivery. Mara has her own plan: she'll help bargain, escape, or expose him. Black moves the van after the second enquiry.`,
        checks: [['btl', 'medium', `Tell Harlan Black, to his face, that Mara is leaving with you`, `He looks at you, at Gita, at Mara. "Not paid enough for this." He leaves.`, `He shrugs. "Then you'd better pay her debt."`],
          ['grf', 'medium', `Get the van delivery records from Gita's office while Black argues`, `Every job: "H. Black — hire — East Cross — 10% to M.R."`, `The drawer's locked.`],
          ['whl', 'hard', `If Black takes Mara in the van, block it at the depot gate`, `Your car across the gate. The van can't leave.`, `It's through.`],
          ['mus', 'medium', `Open the van's back door and get Mara out`, `Out and into your car.`, `It's locked from inside.`]]}
    ],
    closeTitle: `Read aloud: he doesn't own me`,
    close: `Mara Sol sits in the back of your car, sequinned jacket, stage makeup smudged. She holds her phone, looking at a message from a friend. "There's another girl," she says. "Same debt. Same Harlan. Different club." She looks at you. "Get her out too, and I'll tell you everything I know about Owen's meetings." She leans back. "He owns the contract," she says, mostly to herself. "He doesn't own the song." Tern, on the radio, says quietly: "Good work. Over."`,
    notes: [`The decision: decide with Mara whether to get her out, buy out and fight the debt, or seize Black's leverage.`,
      `The Marshgate van delivery records are a physical prop.`,
      `Reward: £240 and 1 TU or VC Renown once. Mara picks her own future bookings and can become a regular contact.`,
      `This is about coercion. Play it seriously; Mara is never a prize, she's a person with a plan.`,
      `Black's vans from East Cross with 10% to Rusk is a thread for MR and LD.`]
  }
};
